import { BrandLogo } from '@refy-design/web';
import { SiteFooter } from '@refy-design/web';
import { ThemeProvider } from '@refy-design/web';
import type { ComponentProps } from 'react';
export function Example() {
  const args: Pick<
    ComponentProps<typeof SiteFooter>,
    'brand' | 'tagline' | 'columns' | 'credits' | 'legal'
  > = {
    brand: <BrandLogo size="sm" symbol aria-label="Refy" />,
    tagline:
      'Ready components, themes made of tokens and rules the AI reads before building the screen.',
    columns: [
      {
        title: 'Product',
        links: [
          { label: 'Docs', href: '#docs' },
          { label: 'Components', href: '#components' },
        ],
      },
      {
        title: 'Project',
        links: [
          { label: 'Repository', href: 'https://example.com/refy', external: true },
        ],
      },
    ],
    credits: 'Created by Vinícius Coimbra.',
    legal: '© 2026 refy · MIT License',
  };
  return (
    <ThemeProvider
      theme={{
        name: 'Footer',
        tokens: {
          '--site-footer-columns': 'repeat(4, minmax(0, 1fr))',
          '--site-footer-heading-weight': '500',
          '--site-footer-link-gap': '8px',
        },
      }}
    >
      <SiteFooter
        {...args}
        data-testid="footer-four"
        columns={[
          {
            title: 'Marketplace',
            links: [
              { label: 'Browse', href: '#browse' },
              { label: 'Sell', href: '#sell' },
              { label: 'Prices', href: '#prices' },
            ],
          },
          {
            title: 'Company',
            links: [
              { label: 'About', href: '#about' },
              { label: 'Careers', href: '#careers' },
            ],
          },
          {
            title: 'Help',
            links: [
              { label: 'Support', href: '#support' },
              { label: 'Safety', href: '#safety' },
            ],
          },
        ]}
      />
    </ThemeProvider>
  );
}
